def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v2 == 0:
        return None

    ratio = v1 / v2
    result = round(ratio)

    return {
        "value": result,
        "trace": {
            "tons_hedged_2017": v1,
            "tons_hedged_2018": v2,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
